-- LogSOC seed: documents referentiels sources (metadata uniquement)
-- file_data (BLOB PDF) et ai_analysis EXCLUS: l'installation re-importe
-- ses propres PDFs si besoin; ici on preserve la tracabilite document_id.
-- Documents publics ANSSI/NIS2/RGPD/DORA/ISO - zero donnee client.
SET NAMES utf8mb4;
/*M!999999\- enable the sandbox mode */ 

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `version` = VALUES(`version`), `description` = VALUES(`description`), `organism` = VALUES(`organism`), `regulatory_framework` = VALUES(`regulatory_framework`), `document_type` = VALUES(`document_type`), `classification_level` = VALUES(`classification_level`), `country` = VALUES(`country`);